import re
from datetime import datetime, timedelta

def parse(path):
    txt=open(path).read()
    evs=[]
    for block in re.findall(r'BEGIN:VEVENT(.*?)END:VEVENT', txt, re.S):
        d={}
        for line in block.strip().splitlines():
            if ':' in line:
                k,v=line.split(':',1); d[k.strip()]=v.strip()
        evs.append((datetime.strptime(d['DTSTART'],'%Y%m%dT%H%M%SZ'),
                    datetime.strptime(d['DTEND'],'%Y%m%dT%H%M%SZ'), d.get('SUMMARY','')))
    return evs

A=parse('/app/alice_calendar.ics'); B=parse('/app/bob_calendar.ics'); C=parse('/app/carol_calendar.ics')

def overlap(s,e,evs):
    return any(s < ee and e > ss for ss,ee,_ in evs)

def alice_ok(s,e,dow):
    return s.hour>=9 and e<=s.replace(hour=14,minute=0) and e.date()==s.date()
def bob_ok(s,e,dow):
    if s.hour<10: return False
    limit = s.replace(hour=16,minute=30) if dow in (1,3) else s.replace(hour=18,minute=0)
    return e<=limit
def carol_ok(s,e,dow):
    if s.hour<9 or e>s.replace(hour=17,minute=0): return False
    # lunch 12:00-12:30
    lunch_s=s.replace(hour=12,minute=0); lunch_e=s.replace(hour=12,minute=30)
    if s<lunch_e and e>lunch_s: return False
    # 15-min buffer after any existing meeting ending >= 16:45
    for ss,ee,_ in C:
        if ee.date()==s.date() and ee.hour*60+ee.minute>=16*60+45:
            if s < ee+timedelta(minutes=15) and e>ee: return False
    return True

start=datetime(2024,1,15,0,0)
end=datetime(2024,1,20,0,0)
valid=[]
t=start
while t<end:
    if t.weekday()<5:
        e=t+timedelta(hours=1)
        if (alice_ok(t,e,t.weekday()) and bob_ok(t,e,t.weekday()) and carol_ok(t,e,t.weekday())
            and not overlap(t,e,A) and not overlap(t,e,B) and not overlap(t,e,C)):
            valid.append(t)
    t+=timedelta(minutes=1)
print("num valid:",len(valid))
for v in valid[:20]:
    print(v.strftime("%a %Y-%m-%d %H:%M"), "-", (v+timedelta(hours=1)).strftime("%H:%M"))
